/**
 * Inbound rail to simulate. `FPS` issues a near-instant Faster Payments
 * credit; `BACS` issues a BACS Direct Credit. Both land via the same
 * scheme-message plumbing the production rails use, so the resulting
 * **Transaction** is indistinguishable from a real inbound at the
 * ledger level.
 *
 */
export type SandboxRail = "FPS" | "BACS";

