export type StandingOrdersResponse = {
  standingOrders: Array<StandingOrderResponse>;
};

/**
 * Verdict from the audit-chain replay verifier. `OK` is the happy
 * path; the four failure modes name where the chain breaks (see
 * `AuditChainVerifier.VerificationResult` for the writer-side contract).
 *
 */
export type AuditChainVerificationResult =
  | "OK"
  | "GAP_AT_SEQ"
  | "PREV_HASH_MISMATCH"
  | "CURRENT_HASH_MISMATCH"
  | "HEAD_MISMATCH";

export type AuditChainVerificationResponse = {
  result: AuditChainVerificationResult;
  /**
   * Number of rows walked. Present iff `result == OK`.
   */
  rowsVerified?: number;
  /**
   * Sequence number where the chain breaks. Present for
   * `GAP_AT_SEQ` / `PREV_HASH_MISMATCH` / `CURRENT_HASH_MISMATCH`.
   *
   */
  atSeq?: number;
};

/**
 * Verdict from the MDR-chain replay verifier over scope `mdr`. `OK` is
 * the happy path; the four failure modes name where the chain breaks —
 * the same shared `VerificationResult` contract as the audit chain.
 *
 */
export type MdrChainVerificationResult =
  | "OK"
  | "GAP_AT_SEQ"
  | "PREV_HASH_MISMATCH"
  | "CURRENT_HASH_MISMATCH"
  | "HEAD_MISMATCH";

export type MdrChainVerificationResponse = {
  result: MdrChainVerificationResult;
  /**
   * Number of rows walked. Present iff `result == OK`.
   */
  rowsVerified?: number;
  /**
   * Sequence number where the chain breaks. Present for
   * `GAP_AT_SEQ` / `PREV_HASH_MISMATCH` / `CURRENT_HASH_MISMATCH`.
   *
   */
  atSeq?: number;
};

/**
 * A human's ruling on a Model Decision. `ACCEPT` makes the Raw output
 * actionable; `EDIT` supplies a full replacement that becomes actionable;
 * `REJECT` bars the output from being acted on.
 *
 */
export type HumanDispositionKind = "ACCEPT" | "EDIT" | "REJECT";

export type RecordHumanDispositionRequest = {
  /**
   * Client-supplied identity of this Entry — the natural idempotency key.
   * A replayed append with the same `entryId` returns the existing Entry.
   *
   */
  entryId: string;
  disposition: HumanDispositionKind;
  /**
   * REQUIRED iff `disposition == EDIT` — the full edited output, stored
   * redacted and hash-covered. Must be absent for `ACCEPT` / `REJECT`.
   *
   */
  editedOutput?: string;
};

export type RecordHumanDispositionResponse = {
  entryId: string;
  decisionId: string;
  /**
   * The Model Decision Entry this ruling is chained after.
   */
  parentEntryId: string;
  /**
   * The Entry's position on the `mdr` chain.
   */
  seq: number;
  disposition: HumanDispositionKind;
};

export type MdrActionableOutputResponse = {
  decisionId: string;
  /**
   * The Ruling in force that made the output actionable.
   */
  ruling: "ACCEPT" | "EDIT";
  /**
   * The Disposition Entry that authorised the output.
   */
  rulingEntryId: string;
  /**
   * The Raw output under `ACCEPT`, or the stored edited output verbatim
   * under `EDIT`. Redacted at write time, exactly as stored.
   *
   */
  actionableOutput: string;
};

export type ExplanationRequest = {
  /**
   * The type half of the Subject ref — the same shape as the MDR's
   * Correlation ref. v1 resolves `PAYMENT` only; further Subject types
   * are additive and need no contract change.
   *
   */
  subjectType: "PAYMENT";
  /**
   * The id half of the Subject ref.
   */
  subjectId: string;
};

export type ExplanationResponse = {
  /**
   * The Model Decision this invocation appended to the MDR chain. Always
   * present — the record exists whether or not an answer could be shown,
   * and replays through the MDR decision-replay read.
   *
   */
  decisionId: string;
  /**
   * How the invocation concluded. `COMPLETED` means an answer arrived —
   * which is not the same as an answer being shown, since it may have
   * failed Grounding. `TIMED_OUT` means the Decider exceeded its
   * configured budget and was abandoned; `ERRORED` means it failed some
   * other way. Under both, no answer exists to show and the Entry
   * carries no Raw output.
   *
   */
  outcome: "COMPLETED" | "TIMED_OUT" | "ERRORED";
  /**
   * The grounded Claims, in Timeline order. Empty when the answer failed
   * Grounding or never arrived — Grounding is all-or-nothing, so a
   * partially-cited narrative is never returned.
   *
   */
  claims: Array<Claim>;
  /**
   * Present only when an answer was produced and then refused, which is
   * the one case a client cannot infer from `outcome` alone: the
   * invocation `COMPLETED`, but a Claim cited a record outside the
   * assembled Timeline or cited nothing, so the whole answer was
   * withheld (ADR-0012). Absent on a served Explanation and absent under
   * `TIMED_OUT` or `ERRORED`, where nothing was produced to refuse.
   *
   * The refused answer is not hidden — it is stored verbatim as the
   * Model Decision's Raw output with its Verdict absent, and replays
   * through `GET /api/v1/admin/mdr/decisions/{decisionId}`.
   *
   */
  refusalCode?: "GROUNDING_FAILED";
};

export type Claim = {
  /**
   * One factual assertion about the Subject.
   */
  text: string;
  /**
   * The Source records this Claim rests on. Every ref here is guaranteed
   * to appear in the recorded Model Decision's retrieved-context refs, so
   * a reader can resolve any citation back to the record it came from.
   *
   */
  sources: Array<SourceRef>;
};

export type SourceRef = {
  /**
   * Which surface owns the cited record. `HOLD` is the ledger reservation
   * placed for the payment; `SCREENING_DECISION` is the decision the
   * payment was referred under, named by the payment row and evidenced on
   * the audit plane rather than read from the MDR (ADR-0009).
   *
   */
  type:
    | "PAYMENT"
    | "HOLD"
    | "SCREENING_DECISION"
    | "AUDIT_EVENT"
    | "LEDGER_ENTRY";
  /**
   * The record's identity on that surface.
   */
  id: string;
};

export type MdrDecisionSummariesResponse = {
  /**
   * One summary per Model Decision, newest first (descending chain seq).
   */
  decisions: Array<MdrDecisionSummary>;
};

export type MdrDecisionSummary = {
  decisionId: string;
  /**
   * The Model Decision Entry's identity.
   */
  entryId: string;
  /**
   * The Entry's position on the `mdr` chain.
   */
  seq: number;
  ts: string;
  outcome: "COMPLETED" | "TIMED_OUT" | "ERRORED";
  modelId: string;
  modelVersion: string;
  /**
   * The type half of the opaque Correlation ref (e.g. `PAYMENT`).
   */
  correlationType: string;
  /**
   * The id half of the opaque Correlation ref.
   */
  correlationId: string;
  /**
   * Whether the Decision declares that no ruling is expected of it — no
   * flow waits on it, so no consumer will request its Actionable output
   * and no reviewer owes it a ruling. It forbids nothing: a Disposition
   * may still be appended and the gate answers exactly as before. False
   * for every Decision written before the field existed.
   *
   */
  advisory: boolean;
  /**
   * How many Human Dispositions have been appended to this Decision.
   */
  dispositionCount: number;
  latencyMs: number;
  costMicros: number;
  costCurrency: string;
  /**
   * The latest Disposition's kind, or absent while the Decision awaits its first ruling.
   */
  rulingInForce?: "ACCEPT" | "EDIT" | "REJECT";
  /**
   * The Decision's structured verdict, exactly as the replay read
   * serves it — absent when unparseable or not produced. Carried on
   * the summary so a reviewer can see what each Decision concluded
   * without opening it; the shape is defined by the prompt template
   * and deliberately unconstrained, same as on MdrModelDecisionView.
   *
   */
  verdict?: {
    [key: string]: unknown;
  };
};

export type MdrDecisionThreadResponse = {
  decisionId: string;
  /**
   * The type half of the opaque Correlation ref (e.g. `PAYMENT`).
   */
  correlationType: string;
  /**
   * The id half of the opaque Correlation ref.
   */
  correlationId: string;
  modelDecision: MdrModelDecisionView;
  /**
   * Every Human Disposition on this Decision, oldest first (chain order).
   */
  dispositions: Array<MdrDispositionView>;
  /**
   * The latest Disposition's kind, or absent when no ruling exists.
   */
  rulingInForce?: "ACCEPT" | "EDIT" | "REJECT";
};

export type MdrModelDecisionView = {
  entryId: string;
  /**
   * The Entry's position on the `mdr` chain.
   */
  seq: number;
  ts: string;
  outcome: "COMPLETED" | "TIMED_OUT" | "ERRORED";
  modelId: string;
  modelVersion: string;
  /**
   * Whether the Decision expects a Human Disposition (ADR-0013). An
   * advisory Decision holds nothing up and never lands on the
   * reviewer's worklist; `false` on Entries recorded before the
   * declaration existed.
   *
   */
  advisory: boolean;
  promptTemplateId: string;
  promptTemplateVersion: string;
  /**
   * Hex-encoded content hash pinning the Prompt template.
   */
  promptTemplateHash: string;
  /**
   * The exact (redacted) text the model saw, stored inline for replay.
   */
  renderedPrompt: string;
  /**
   * The context refs the model decided from, as Correlation-style refs
   * with content hashes; absent when none. Provenance, not payload:
   * refs point at mutable rows in other contexts, and the hash is
   * detection, not recovery.
   *
   */
  retrievedContext?: Array<MdrRetrievedContextRef>;
  /**
   * The model's output verbatim modulo redaction. Present iff `outcome == COMPLETED`.
   */
  rawOutput?: string;
  /**
   * Structured verdict parsed from the Raw output; absent when
   * unparseable or not produced. Its shape is defined by the prompt
   * template identified by `promptTemplateId` and varies across
   * templates; the record deliberately leaves it unconstrained and
   * stores what the model actually produced. Treat as opaque
   * structured JSON.
   *
   */
  verdict?: {
    [key: string]: unknown;
  };
  /**
   * Failure detail. Present iff `outcome == ERRORED`.
   */
  errorDetail?: string;
  latencyMs: number;
  costMicros: number;
  costCurrency: string;
};

export type MdrRetrievedContextRef = {
  /**
   * The type half of the Correlation-style ref (e.g. `AUTHORISATION_HISTORY`).
   */
  type: string;
  /**
   * The id half of the Correlation-style ref, naming the row the context came from.
   */
  id: string;
  /**
   * Content hash of the context as retrieved, pinning what the model actually saw.
   */
  contentHash: string;
};

export type MdrDispositionView = {
  entryId: string;
  seq: number;
  ts: string;
  disposition: HumanDispositionKind;
  /**
   * The admin who ruled, from the authenticated principal.
   */
  humanId: string;
  /**
   * The Model Decision Entry this ruling is chained after.
   */
  parentEntryId: string;
  /**
   * The stored replacement; present iff `disposition == EDIT`.
   */
  editedOutput?: string;
  /**
   * Line-level difference from the Raw output, derived at read time for
   * an EDIT ruling and never stored. Absent for ACCEPT / REJECT.
   *
   */
  diff?: Array<MdrDiffLine>;
};

export type MdrDiffLine = {
  op: "UNCHANGED" | "REMOVED" | "ADDED";
  text: string;
};

/**
 * Whether a Metric carries a value. `UNAVAILABLE` means the context that
 * owns the underlying facts could not be reached or did not answer within
 * its timeout — the response is still a success, one number is simply not
 * known. Never a stand-in for zero.
 *
 */
export type MetricStatus = "AVAILABLE" | "UNAVAILABLE";

export type CountMetric = {
  status: MetricStatus;
  /**
   * Present if and only if `status` is `AVAILABLE`.
   */
  count?: number;
};

export type MoneyMetric = {
  status: MetricStatus;
  /**
   * Present if and only if `status` is `AVAILABLE`.
   */
  amountMinorUnits?: number;
  /**
   * Present if and only if `status` is `AVAILABLE`. GBP only — non-GBP
   * payments are excluded from the figure rather than summed into it.
   *
   */
  currency?: "GBP";
};

export type ExecMetricsResponse = {
  /**
   * The trailing window these figures cover, echoed back.
   */
  window: "TODAY" | "LAST_7_DAYS" | "LAST_30_DAYS" | "LAST_12_MONTHS";
  /**
   * The first Banking day the figures cover, in `Europe/London`.
   * Equals `bankingDay` when the window is `TODAY`.
   *
   */
  windowStart: string;
  /**
   * The current Banking day — the window's last day, in `Europe/London`.
   */
  bankingDay: string;
  /**
   * The moment the figures were taken.
   */
  asOf: string;
  newCustomers: CountMetric;
  deposits: MoneyMetric;
  cardsIssued: CountMetric;
  paymentsStopped: MoneyMetric;
};

/**
 * The Case lifecycle. `OPEN` — Alerts have landed, no officer has
 * acted. `INVESTIGATING` — the first officer action (a Disposition on
 * a linked Alert, or a SAR draft request) has been taken. Terminal:
 * `CLOSED_DISMISSED` (no suspicion survived) and `CLOSED_REPORTED`
 * (the SAR narrative was ruled actionable through the Gate and
 * attached). Terminal transitions are Gate-governed (ADR-0014).
 *
 */
export type AmlCaseStatus =
  | "OPEN"
  | "INVESTIGATING"
  | "CLOSED_DISMISSED"
  | "CLOSED_REPORTED";

/**
 * The pattern an Alert detects. `STRUCTURING` — several outbound
 * payments to one beneficiary, individually under the screening
 * threshold, jointly at or above it. `RAPID_IN_OUT` — an inbound
 * credit drained back out within a short window. `HIGH_RISK_CORRIDOR`
 * — a SWIFT payment whose beneficiary jurisdiction, derived from its
 * IBAN or BIC, is on the versioned high-risk list.
 *
 */
export type AmlTypology = "STRUCTURING" | "RAPID_IN_OUT" | "HIGH_RISK_CORRIDOR";

export type AmlCaseSummariesResponse = {
  /**
   * One summary per Case, newest opened first.
   */
  cases: Array<AmlCaseSummary>;
};

export type AmlCaseSummary = {
  caseId: string;
  /**
   * The subject account under investigation.
   */
  accountId: string;
  status: AmlCaseStatus;
  /**
   * How many Alerts are linked to this Case.
   */
  alertCount: number;
  openedAt: string;
  /**
   * The last time an Alert attached or the status moved.
   */
  updatedAt: string;
};

export type AmlCaseDetailResponse = {
  caseId: string;
  /**
   * The subject account under investigation.
   */
  accountId: string;
  status: AmlCaseStatus;
  openedAt: string;
  /**
   * The last time an Alert attached or the status moved.
   */
  updatedAt: string;
  /**
   * Every Alert linked to the Case, oldest first.
   */
  alerts: Array<AmlAlertView>;
  /**
   * The SAR state; absent until a draft has been requested.
   */
  sar?: AmlSarView;
};

export type AmlAlertView = {
  /**
   * The Alert's Model Decision on the `mdr` chain — the id the Ops
   * surface uses to drive the MDR disposition door and replay read.
   *
   */
  decisionId: string;
  typology: AmlTypology;
  /**
   * The rule-assigned risk score (0–100) carried in the Decision's verdict.
   */
  riskScore: number;
  raisedAt: string;
  /**
   * The latest Disposition on the Alert's decision, or absent while
   * it awaits its first ruling. Any ruling clears the Alert from the
   * MDR worklist; a REJECT shows it cleared as a false positive.
   *
   */
  rulingInForce?: "ACCEPT" | "EDIT" | "REJECT";
  /**
   * The settled payments the pattern was found over, oldest first.
   */
  evidence: Array<AmlEvidencePayment>;
};

export type AmlEvidencePayment = {
  paymentId: string;
  /**
   * Hex content hash of the payment as the Decider saw it — the same
   * hash pinned in the Alert decision's retrieved-context ref, so
   * the row on screen is checkable against what the model cited.
   *
   */
  contentHash: string;
  rail: Rail;
  direction: "OUTBOUND" | "INBOUND";
  amountMinorUnits: number;
  currency: Currency;
  createdAt: string;
  beneficiaryName?: string;
  /**
   * UK sort code in `XX-XX-XX` form; absent on SWIFT payments.
   */
  beneficiarySortCode?: string;
  /**
   * 8-digit UK account number; absent on SWIFT payments.
   */
  beneficiaryAccountNo?: string;
  /**
   * Present on SWIFT payments; jurisdiction derives from characters 1–2.
   */
  beneficiaryIban?: string;
  /**
   * Present on SWIFT payments; jurisdiction derives from characters 5–6.
   */
  beneficiaryBic?: string;
};

export type AmlSarView = {
  /**
   * The SAR draft's Model Decision on the `mdr` chain — the decision
   * close-as-reported consults through the Gate, and the id the Ops
   * surface uses to rule on the draft via the MDR disposition door.
   *
   */
  decisionId: string;
  /**
   * The latest Disposition on the SAR decision, or absent while it awaits ruling.
   */
  rulingInForce?: "ACCEPT" | "EDIT" | "REJECT";
  /**
   * The attached narrative, exactly as ruled (the edited output
   * under an EDIT). Present if and only if the Case is
   * `CLOSED_REPORTED`.
   *
   */
  narrative?: string;
};

export type AmlSarDraftResponse = {
  /**
   * The Model Decision this draft appended to the MDR chain. Always
   * present — the record exists whether or not a narrative could be
   * served — and replays through the MDR decision replay read.
   *
   */
  decisionId: string;
  /**
   * How the invocation concluded. `COMPLETED` means a narrative
   * arrived — not the same as one being served, since it may have
   * failed Grounding. `TIMED_OUT` and `ERRORED` carry no narrative;
   * the missing answer is a recorded fact on the chain.
   *
   */
  outcome: "COMPLETED" | "TIMED_OUT" | "ERRORED";
  /**
   * The drafted SAR narrative, present when it arrived and every
   * claim cited inside the assembled timeline. This draft is not yet
   * the Case's filed narrative — that happens only at
   * close-as-reported, through the Gate.
   *
   */
  narrative?: string;
  /**
   * Present only when a narrative was produced and then refused: the
   * invocation `COMPLETED`, but a citation strayed outside the
   * assembled timeline (or the draft cited nothing), so the whole
   * draft was withheld. The refused draft is not hidden — it is
   * stored verbatim as the Model Decision's Raw output with its
   * verdict absent, and replays through
   * `GET /api/v1/admin/mdr/decisions/{decisionId}`.
   *
   */
  refusalCode?: "GROUNDING_FAILED";
};

